import { useMemo, type ReactNode } from 'react';
import {
  RouterProvider,
  createBrowserRouter,
  createHashRouter,
  createMemoryRouter,
  type RouteObject,
} from 'react-router-dom';
import { createRouteObjects } from './createRoutes.js';
import type { TRouteTree } from './types.js';

export type TFileRouterProviderProps = {
  /** The `routes` object generated by ts-file-router */
  routes: TRouteTree;
  /** Rendered while a lazy page is loading */
  fallback?: ReactNode;
  /** Rendered for unmatched URLs */
  notFound?: ReactNode;
  /** Rendered when a route throws */
  errorElement?: ReactNode;
  /** Router flavour. Defaults to 'browser' */
  mode?: 'browser' | 'hash' | 'memory';
  /** Only used by 'memory' mode */
  initialEntries?: string[];
  basename?: string;
};

export const FileRouterProvider = ({
  routes,
  fallback = null,
  notFound,
  errorElement,
  mode = 'browser',
  initialEntries,
  basename,
}: TFileRouterProviderProps) => {
  const router = useMemo(() => {
    const objects: RouteObject[] = createRouteObjects(routes, fallback);

    if (notFound) {
      objects.push({ path: '*', element: notFound });
    }

    if (errorElement) {
      objects.forEach((route) => {
        route.errorElement = errorElement;
      });
    }

    if (mode === 'hash') return createHashRouter(objects, { basename });
    if (mode === 'memory') {
      return createMemoryRouter(objects, { basename, initialEntries });
    }

    return createBrowserRouter(objects, { basename });
  }, [routes, fallback, notFound, errorElement, mode, initialEntries, basename]);

  return <RouterProvider router={router} />;
};
